mapper.select:
SELECT T.ROLE_ID, T.ROLE_NAME, T.REMARK, T.DELEGABLE, T.CREATE_USER_ID, T.CREATE_USER_ORG_NO, T.CREATE_TIME FROM SYS_ROLE T WHERE 1=1
AND (T.CREATE_USER_ID=#{params.roleViewer}
OR (T.DELEGABLE=1 AND EXISTS (SELECT 1 FROM SYS_ROLE_ORG O WHERE O.ROLE_ID=T.ROLE_ID) AND NOT EXISTS (SELECT 1 FROM SYS_ROLE_ORG O WHERE O.ROLE_ID=T.ROLE_ID AND O.ORG_NO NOT IN #{org} ))
)
AND T.ROLE_NAME LIKE CONCAT('%', #{params.roleName}, '%')
